items.push(item('onboarding-wizard','Onboarding wizard','feedback','A three-step onboarding flow with progress, back navigation, and editable selections.',['Interactive','Minimal'],
`<div class="demo wizard"><header><span class="wizard-step">01 / 03</span><span>MAKE IT YOURS</span></header><div class="wizard-progress"><i class="active"></i><i></i><i></i></div><div class="wizard-panel"><span class="wizard-symbol">✳</span><h2>A space for your ideas.</h2><p>What should we call your workspace?</p><label><span>Workspace name</span><input value="The next good thing" aria-label="Workspace name"></label></div><footer><button class="wizard-back" disabled>← Back</button><button class="primary wizard-next">Continue ↗</button></footer></div>`,
`.wizard{max-width:360px;padding:22px;border:1px solid #4c4c4c;border-radius:12px;background:#1f1f1f}.wizard header{display:flex;justify-content:space-between;align-items:center;font-size:6px;color:#858585;letter-spacing:.08em}.wizard-step{color:var(--lime);font-size:8px}.wizard-progress{display:flex;gap:5px;margin-top:12px}.wizard-progress i{height:2px;flex:1;background:#404040}.wizard-progress i.active{background:var(--lime)}.wizard-panel{margin:23px 0}.wizard-symbol{font-size:32px;color:var(--lime);line-height:1}.wizard h2{font-size:clamp(20px,5.4vw,28px);line-height:1.1;letter-spacing:-.05em;font-weight:450;margin:13px 0 8px}.wizard-panel>p{font-size:9px;color:#9f9f9f}.wizard label{display:block;margin-top:18px}.wizard label>span{display:block;font-size:7px;color:#9b9b9b;margin-bottom:5px}.wizard input,.wizard select{width:100%;padding:9px;border:1px solid #5e5e5e;background:#313131;color:#e4e4e4;border-radius:5px;font-size:10px}.wizard footer{display:flex;justify-content:space-between;align-items:center;border-top:1px solid #404040;padding-top:14px}.wizard-back{background:none;color:#a8a8a8;font-size:9px!important;padding:0}.wizard-back:disabled{opacity:.3}.wizard-next{font-size:9px!important}`,
`let step=0,name='The next good thing',intent='Personal projects';const panel=document.querySelector('.wizard-panel'),next=document.querySelector('.wizard-next'),back=document.querySelector('.wizard-back');function render(){document.querySelector('.wizard-step').textContent='0'+(step+1)+' / 03';document.querySelectorAll('.wizard-progress i').forEach((i,n)=>i.classList.toggle('active',n<=step));back.disabled=step===0;if(step===0){panel.innerHTML='<span class="wizard-symbol">✳</span><h2>A space for your ideas.</h2><p>What should we call your workspace?</p><label><span>Workspace name</span><input aria-label="Workspace name"></label>';panel.querySelector('input').value=name;next.textContent='Continue ↗'}if(step===1){panel.innerHTML='<span class="wizard-symbol">↗</span><h2>Find your direction.</h2><p>What will you make room for?</p><label><span>Your focus</span><select aria-label="Workspace focus"><option>Personal projects</option><option>Creative work</option><option>Team collaboration</option></select></label>';panel.querySelector('select').value=intent;next.textContent='Continue ↗'}if(step===2){panel.innerHTML='<span class="wizard-symbol">✓</span><h2>Ready when you are.</h2><p></p><label><span>YOUR NEXT CHAPTER</span><div style="padding:13px;background:#313131;border-radius:6px;font-size:11px;color:#ececec"></div></label>';panel.querySelector('p').textContent=name+' · '+intent;panel.querySelector('label div').textContent='A little structure. A lot of possibility.';next.textContent='Start again ↺'}}next.onclick=()=>{if(step===0){name=panel.querySelector('input').value.trim()||'Untitled workspace'}if(step===1)intent=panel.querySelector('select').value;step=(step+1)%3;render()};back.onclick=()=>{if(step>0){step--;render()}};`,true));

items.push(item('mobile-bottom-sheet','Mobile bottom sheet','feedback','A contained mobile action sheet with selectable export formats and a working download.',['Interactive','Minimal'],
`<div class="demo bottom-sheet-demo"><div class="sheet-context"><span>↧</span><h2>Keep a little inspiration.</h2><p class="muted">Your ideas deserve to travel.</p><button class="primary open-sheet">Export your collection ↗</button></div><dialog class="bottom-sheet"><div class="sheet-handle"></div><header><h3>A format for every idea.</h3><button class="close-sheet" aria-label="Close export options">×</button></header><p>Choose how to take your collection with you.</p><div class="format-options"><button class="selected" data-format="txt" aria-pressed="true"><span>≡</span><b>Plain text</b><small>Simple & portable</small></button><button data-format="json" aria-pressed="false"><span>{ }</span><b>JSON</b><small>A little structure</small></button><button data-format="md" aria-pressed="false"><span>↓</span><b>Markdown</b><small>Ready to write</small></button></div><button class="primary export-collection">Download collection ↗</button><small class="export-foot">A tiny sample, made for this preview.</small></dialog></div>`,
`.sheet-context{text-align:center;padding:24px 10px}.sheet-context>span{font-size:35px;line-height:1;color:var(--lime)}.sheet-context h2{font-size:clamp(18px,4.8vw,27px);font-weight:450;letter-spacing:-.05em;margin:15px 0 7px}.sheet-context p{font-size:10px;margin-bottom:19px}.bottom-sheet{position:fixed;inset:auto 0 0;width:min(100%,520px);max-width:none;margin:auto;padding:10px 24px 23px;background:#212121;color:#f2f2f2;border:1px solid #5f5f5f;border-bottom:0;border-radius:18px 18px 0 0;box-shadow:0 -20px 70px #00000066}.bottom-sheet::backdrop{background:#00000099;backdrop-filter:blur(3px)}.sheet-handle{width:30px;height:3px;border-radius:2px;background:#5f5f5f;margin:0 auto 18px}.bottom-sheet header{display:flex;align-items:center;justify-content:space-between}.bottom-sheet h3{font-size:18px;font-weight:450;letter-spacing:-.035em}.close-sheet{font-size:22px;background:none;color:#9e9e9e;padding:0}.bottom-sheet>p{font-size:9px;color:#a2a2a2;margin-top:6px}.format-options{display:flex;gap:8px;margin:20px 0 17px}.format-options>button{flex:1;border:1px solid #4f4f4f;background:#2a2a2a;border-radius:7px;padding:13px 7px;color:#a3a3a3;display:flex;align-items:center;flex-direction:column}.format-options>button.selected{border-color:#cbcbcb;background:#3b3b3b;color:var(--lime)}.format-options span{font-size:20px;line-height:1.1;height:25px}.format-options b{font-size:9px;font-weight:450;margin-top:7px}.format-options small{font-size:6px;margin-top:3px;color:#929292}.export-collection{width:100%}.export-foot{display:block;font-size:7px;color:#747474;text-align:center;margin-top:11px}`, 
`const dialog=document.querySelector('dialog');let format='txt';document.querySelector('.open-sheet').onclick=()=>dialog.showModal();document.querySelector('.close-sheet').onclick=()=>dialog.close();document.querySelectorAll('.format-options button').forEach(b=>b.onclick=()=>{format=b.dataset.format;document.querySelectorAll('.format-options button').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))})});document.querySelector('.export-collection').onclick=()=>{const content=format==='json'?JSON.stringify({collection:'Small beginnings',ideas:['Stay curious','Make room','Begin again']},null,2):format==='md'?'# Small beginnings\\n\\n- Stay curious\\n- Make room\\n- Begin again':'Small beginnings\\n\\nStay curious\\nMake room\\nBegin again';const url=URL.createObjectURL(new Blob([content],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='small-beginnings.'+format;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('.export-foot').textContent='✓ Your sample collection is ready.'};`));

items.push(item('error-recovery','Error recovery','feedback','A friendly failure state with a retry cycle and a successful recovery.',['Interactive','Animated'],
`<div class="demo error-recovery"><div class="recovery-art"><span>!</span><i></i><i></i></div><span class="eyebrow">A SMALL DETOUR</span><h2>Let's try that again.</h2><p class="muted recovery-copy">A little hiccup along the way.<br>Your ideas are right where you left them.</p><button class="primary retry-action">Give it another go ↻</button><small class="recovery-code">DEMO_STATE / CONNECTION_PAUSED</small></div>`,
`.error-recovery{text-align:center;display:grid;justify-items:center;max-width:360px}.recovery-art{position:relative;width:85px;height:65px;margin-bottom:14px}.recovery-art>span{display:grid;place-items:center;width:48px;height:48px;position:absolute;left:18px;top:8px;border:1px solid #838383;background:#393939;color:var(--lime);border-radius:13px;font:30px Georgia,serif;transform:rotate(-9deg)}.recovery-art i{position:absolute;border:1px solid #565656;width:14px;height:14px;border-radius:50%;left:0;top:5px}.recovery-art i:last-child{width:6px;height:6px;left:auto;right:0;top:49px;background:#ececec44}.error-recovery .eyebrow{font-size:6px;letter-spacing:.15em}.error-recovery h2{font-size:clamp(25px,6vw,35px);font-weight:450;letter-spacing:-.05em;margin:12px 0 9px}.error-recovery p{font-size:10px;line-height:1.8}.retry-action{margin-top:20px;min-width:175px}.retry-action:disabled{opacity:.65;cursor:wait}.recovery-code{font-family:ui-monospace,monospace;color:#616161;font-size:5px;letter-spacing:.06em;margin-top:14px}.recovering .recovery-art>span{animation:recoverSpin .8s ease-in-out infinite}@keyframes recoverSpin{50%{transform:rotate(9deg)}}`,
`let done=false;document.querySelector('.retry-action').onclick=e=>{if(done){done=false;document.querySelector('h2').textContent="Let's try that again.";document.querySelector('.recovery-copy').innerHTML='A little hiccup along the way.<br>Your ideas are right where you left them.';document.querySelector('.recovery-art>span').textContent='!';e.currentTarget.textContent='Give it another go ↻';return}const b=e.currentTarget;b.disabled=true;b.textContent='Finding our way…';document.querySelector('.demo').classList.add('recovering');setTimeout(()=>{done=true;b.disabled=false;b.textContent='Replay the journey ↺';document.querySelector('.demo').classList.remove('recovering');document.querySelector('.recovery-art>span').textContent='✓';document.querySelector('h2').textContent='Back to a good place.';document.querySelector('.recovery-copy').innerHTML='Everything is right where it belongs.<br>Carry on with your next great idea.';document.querySelector('.recovery-code').textContent='DEMO_STATE / ALL_SYSTEMS_GOOD'},1600)};`));

